.r3--tall { min-height: 200dvh; contain-intrinsic-size: auto 200dvh; }
.r3--paper2 { background: var(--paper-2); }

@media (max-width: 640px) {
  .frames { --head-h: 196px; }
  .head { height: 196px; padding-top: 24px; }
  .mailto { top: 22px; font-size: 13px; }
  .head__line { top: 62px; height: 76px; }
  /* Below 640 the line is allowed to wrap. It never changes line count DURING
     the act, which is what the one-line rule protects. */
  .h1 { white-space: normal; }
  /* 42 % of a 390 px stage is 164 px, and the label sits 20 px off the seam, so
     neither block can reach an edge and nothing overflows. Read off
     fold-390.png, where 62 % pushed the Calyx caption past the right edge. */
  .tag { top: 150px; width: 44%; }
  .tag--before { right: calc(100% + 12px); }
  .tag--after  { left: 12px; }
}
</style>
</head>
<body>

