              const fr=document.querySelector('.frames'), ifr=document.querySelector('.layer--before iframe');
              const cs=getComputedStyle(act);
              const fb=fr.getBoundingClientRect(), ib=ifr.getBoundingClientRect();
              const stage=document.querySelector('.split__ground').getBoundingClientRect();
              return {ov: de.scrollWidth>de.clientWidth, scale: cs.getPropertyValue('--frame-scale').trim(),
