/* Position truth for the solve, deliberately the RAW --sc-p and not the
   smoothed twin: --sc-ps lags by design, so immediately after an instant
   scroll it still reports where the reader was, and a second press would
   compound the error. F-014 governs what may DRIVE visible motion; nothing
   here is painted, this only decides how far to scroll. */
function readPsRaw() {
  var v = parseFloat(getComputedStyle(act).getPropertyValue('--sc-p'));
  return isNaN(v) ? 0 : v;
}
/* Scroll position is not ps: the engine applies its own dwell remap
   (data-sc-dwell="0.22"), so a fixed slice of scroll is a varying slice of
   ps. Solving on the ps axis and then correcting once against the achieved
   position absorbs that without depending on the engine's internals.
   Measured before the correction existed: one press moved 0.93 % of the stage
   in the drift and 2.00 % in the rush, against a required 1.5–3 %. */
function nudge(dirSign) {
  var travel = act.offsetHeight - innerHeight;
  var here = readPsRaw();
  var wanted = clamp01(targetFrom(here) + dirSign * KEY_STEP);
  scrollBy({ top: (psForSplit(wanted) - here) * travel, behavior: 'instant' });
  requestAnimationFrame(function () {
    var now = readPsRaw();
    if (Math.abs(targetFrom(now) - wanted) > 0.002) {
      scrollBy({ top: (psForSplit(wanted) - now) * travel, behavior: 'instant' });
    }
    wake();
  });
}
hit.addEventListener('keydown', function (e) {
  var travel = act.offsetHeight - innerHeight;
  if (e.key === 'ArrowRight' || e.key === 'ArrowDown') { e.preventDefault(); nudge(-1); }
  else if (e.key === 'ArrowLeft' || e.key === 'ArrowUp') { e.preventDefault(); nudge(1); }
  else if (e.key === 'End')  { e.preventDefault(); scrollBy({ top: (1 - readPsRaw()) * travel, behavior: 'instant' }); wake(); }
  else if (e.key === 'Home') { e.preventDefault(); scrollBy({ top: -readPsRaw() * travel, behavior: 'instant' }); wake(); }
});

