input.new_string:
/* split and drag are the fold, so they are the start value. mid and degraded
   are fractions of the journey, so they derive from it too — otherwise
   "mid-degradation" would mean a different amount of degradation than it did
   before the start value moved. */
var MODES = {
  before: 1,
  split: SPLIT_START,
  after: 0,
  mid: SPLIT_START * 0.5,
  degraded: SPLIT_START * 0.2,
  drag: SPLIT_START
};

