import asyncio
from playwright.async_api import async_playwright
async def main():
    async with async_playwright() as p:
        b=await p.chromium.launch()
        for w,h in [(1440,900),(390,844)]:
            pg=await b.new_page(viewport={'width':w,'height':h})
            await pg.goto('http://127.0.0.1:3303/tests/alunix-r8/runs/K4/index.html', wait_until='networkidle')
            await pg.wait_for_timeout(1600)
            r=await pg.evaluate('''()=>{
              const g=document.querySelector('.split__ground').getBoundingClientRect();
              const sp=parseFloat(getComputedStyle(document.getElementById('split')).getPropertyValue('--split'));
              const seam=g.left+sp*g.width;
              const sc=parseFloat(getComputedStyle(document.getElementById('split')).getPropertyValue('--frame-scale'))||1;
              const out={seam:Math.round(seam*10)/10, scale:sc};
              const fa=document.getElementById('frameAfter').contentDocument;
              const fb=document.getElementById('frameBefore').contentDocument;
              if(fa){const m=[...fa.querySelectorAll('a')].find(e=>e.textContent.trim()==='Calyx');
                if(m){const bb=m.getBoundingClientRect();
                  // glyph box: use a range around the text
                  const rg=fa.createRange(); rg.selectNodeContents(m); const rb=rg.getBoundingClientRect();
                  out.calyxRight=Math.round((g.left+rb.right*sc)*10)/10;}}
              if(fb){const items=[...fb.querySelectorAll('header nav a')].map(e=>{const rg=fb.createRange();rg.selectNodeContents(e);const rb=rg.getBoundingClientRect();
                  return [e.textContent.trim(), g.left+rb.left*sc, g.left+rb.right*sc];});
                let best=null;
                items.forEach(([t,l,rr])=>{const d=Math.min(Math.abs(seam-l),Math.abs(seam-rr));
                  if(l<seam&&rr>seam){best=['CUTS '+t,0];}
                  else if(!best||d<best[1])best=best&&best[1]<d?best:[t,d];});
                out.nearestNav=best[0]; out.navGap=Math.round(best[1]*10)/10;}
              return out;}''')
            print(w, r)
            if 'calyxRight' in r: print('   seam - calyx wordmark right = %.1f px' % (r['seam']-r['calyxRight']))
            await pg.close()
        await b.close()
asyncio.run(main())
" 2>&1 | tail -6

